function Templates({ types, departments, reload }: { types: RequestType[]; departments: Department[]; reload: () => void }) { const [editing, setEditing] = useState<RequestType | 'new' | null>(null), [error, setError] = useState(''); const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); setError(''); const v = Object.fromEntries(new FormData(e.currentTarget)) as Record<string, string>; try { const fields = v.templateFields ? JSON.parse(v.templateFields) : []; await api(editing === 'new' ? '/request-types' : `/request-types/${(editing as RequestType).id}`, { method: editing === 'new' ? 'POST' : 'PATCH', body: JSON.stringify({ ...v, departmentId: Number(v.departmentId), isActive: v.isActive === 'on', requiresOrganization: v.requiresOrganization === 'on', requiresStore: v.requiresStore === 'on', availableOnWeb: v.availableOnWeb === 'on', availableOnTelegram: v.availableOnTelegram === 'on', templateFields: fields }) }); setEditing(null); reload() } catch (reason) { setError(reason instanceof SyntaxError ? 'Поля шаблона указаны в неверном формате' : errorText(reason)) } }; return <><div className="section-actions"><span>{types.filter(t => t.isActive).length} активных шаблонов</span><Button onClick={() => setEditing('new')}><Plus /> Новый шаблон</Button></div><div className="type-grid">{types.map(t => <article className="type-card" key={t.id}><i style={{ background: t.color || '#ee7d6a' }} /><div><h3>{t.name}</h3><p>{t.description || 'Без описания'}<br />{t.department.name} · {priorityLabel[t.defaultPriority]}</p><span>{t.isActive ? 'Активен' : 'Отключён'} · полей: {t.templateFields?.length ?? 0}</span></div><Button kind="ghost" onClick={() => setEditing(t)}><Pencil /></Button></article>)}</div>{editing && <Modal title={editing === 'new' ? 'Новый шаблон' : 'Настройка шаблона'} close={() => setEditing(null)} wide><form onSubmit={submit}><div className="form-grid"><Field label="Название"><input name="name" required defaultValue={editing === 'new' ? '' : editing.name} /></Field><Field label="Отдел"><select name="departmentId" defaultValue={editing === 'new' ? departments[0]?.id : editing.departmentId}>{departments.map(d => <option value={d.id} key={d.id}>{d.name}</option>)}</select></Field></div><Field label="Описание"><textarea name="description" defaultValue={editing === 'new' ? '' : editing.description ?? ''} /></Field><div className="form-grid"><Field label="Цвет"><input name="color" type="color" defaultValue={editing === 'new' ? '#ee7d6a' : editing.color ?? '#ee7d6a'} /></Field><Field label="Начальный приоритет"><select name="defaultPriority" defaultValue={editing === 'new' ? 'NORMAL' : editing.defaultPriority}>{Object.entries(priorityLabel).map(([v, l]) => <option value={v} key={v}>{l}</option>)}</select></Field></div><div className="checkbox-row"><label><input name="isActive" type="checkbox" defaultChecked={editing === 'new' || editing.isActive} /> Активен</label><label><input name="requiresOrganization" type="checkbox" defaultChecked={editing === 'new' || editing.requiresOrganization} /> Требовать организацию</label><label><input name="requiresStore" type="checkbox" defaultChecked={editing === 'new' || editing.requiresStore} /> Требовать точку</label><label><input name="availableOnWeb" type="checkbox" defaultChecked={editing === 'new' || editing.availableOnWeb} /> Сайт</label><label><input name="availableOnTelegram" type="checkbox" defaultChecked={editing === 'new' || editing.availableOnTelegram} /> Telegram</label></div><Field label="Дополнительные поля (JSON)"><textarea name="templateFields" rows={7} defaultValue={editing === 'new' ? '[]' : JSON.stringify(editing.templateFields ?? [], null, 2)} /><small>Пример: [{'{"key":"serial","label":"Серийный номер","type":"TEXT","required":true}'}]</small></Field>{error && <div className="form-error">{error}</div>}<div className="modal-actions"><Button kind="secondary" type="button" onClick={() => setEditing(null)}>Отмена</Button><Button>Сохранить</Button></div></form></Modal>}</> }

function Staff({ staff, departments, reload }: { staff: StaffMember[]; departments: Department[]; reload: () => void }) { const [editing, setEditing] = useState<StaffMember | 'new' | null>(null), [error, setError] = useState(''), [telegramLink, setTelegramLink] = useState<{ deepLink: string; expiresAt: string } | null>(null); const submit = async (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); setError(''); const form = new FormData(e.currentTarget); const role = String(form.get('role')) as StaffMember['role']; const ids = form.getAll('departments').map(Number); const permissions = (Object.keys(permissionLabels) as PermissionKey[]).map(permission => ({ permission, enabled: form.get(`permission-${permission}`) === 'on' })); try { if (editing === 'new') await api('/staff', { method: 'POST', body: JSON.stringify({ name: form.get('name'), email: form.get('email'), phone: form.get('phone'), password: form.get('password'), role, departmentIds: ids }) }); else await api(`/staff/${editing!.id}/access`, { method: 'PUT', body: JSON.stringify({ role, departments: ids.map(departmentId => ({ departmentId, membershipRole: role === 'DEPARTMENT_HEAD' ? 'HEAD' : 'MASTER' })), permissions }) }); setEditing(null); reload() } catch (reason) { setError(errorText(reason)) } }; const createTelegramLink = async (id: number) => { try { setError(''); setTelegramLink(await api<{ deepLink: string; expiresAt: string }>(`/staff/${id}/telegram-link`, { method: 'POST' })) } catch (reason) { setError(errorText(reason)) } }; return <><div className="section-actions"><span>{staff.length} сотрудников</span><Button onClick={() => setEditing('new')}><Plus /> Добавить сотрудника</Button></div><section className="panel data-table"><div className="table-row table-head"><span>Сотрудник</span><span>Роль</span><span>Отделы</span><span>Статус</span><span /></div>{staff.map(person => <div className="table-row" key={person.id}><span><b>{person.ipName}</b><small>{person.email} · {person.phone}</small></span><span>{roleLabel[person.role]}</span><span>{person.departmentMemberships.map(d => d.department.name).join(', ') || '—'}</span><span>{person.status === 'ACTIVE' ? 'Активен' : 'Заблокирован'}</span><span><Button kind="ghost" onClick={() => setEditing(person)}><UserRoundCog /></Button></span></div>)}</section>{editing && <Modal title={editing === 'new' ? 'Новый сотрудник' : `Права: ${editing.ipName}`} close={() => setEditing(null)} wide><form onSubmit={submit}>{editing === 'new' && <><div className="form-grid"><Field label="Имя"><input name="name" required /></Field><Field label="Телефон"><input name="phone" required /></Field></div><div className="form-grid"><Field label="Email"><input name="email" type="email" required /></Field><Field label="Временный пароль"><input name="password" minLength={8} required /></Field></div></>}<Field label="Роль"><select name="role" defaultValue={editing === 'new' ? 'MASTER' : editing.role}>{(['DIRECTOR', 'DEPARTMENT_HEAD', 'MASTER'] as const).map(role => <option value={role} key={role}>{roleLabel[role]}</option>)}</select></Field><div className="permission-grid"><div><b>Отделы</b>{departments.map(d => <label key={d.id}><input name="departments" type="checkbox" value={d.id} defaultChecked={editing !== 'new' && editing.departmentMemberships.some(m => m.departmentId === d.id)} /> {d.name}</label>)}</div><div><b>Индивидуальные разрешения</b>{(Object.keys(permissionLabels) as PermissionKey[]).map(key => <label key={key}><input name={`permission-${key}`} type="checkbox" defaultChecked={editing !== 'new' ? editing.permissionOverrides.find(p => p.permission === key)?.enabled ?? defaultPermissions[editing.role].includes(key) : false} /> {permissionLabels[key]}</label>)}</div></div>{editing !== 'new' && <section className="telegram-link"><div><b>Рабочий Telegram</b><p>{editing.linkedTelegramChats?.length ? <>Подключён: @{editing.linkedTelegramChats[0].username ?? editing.linkedTelegramChats[0].title}</> : 'Не подключён'}</p></div><Button type="button" kind="secondary" onClick={() => void createTelegramLink(editing.id)}>{editing.linkedTelegramChats?.length ? 'Новая ссылка' : 'Подключить Telegram'}</Button>{telegramLink && <a className="link-button" href={telegramLink.deepLink} target="_blank" rel="noreferrer">Открыть ссылку (20 мин.)</a>}</section>}{error && <div className="form-error">{error}</div>}<div className="modal-actions"><Button type="button" kind="secondary" onClick={() => setEditing(null)}>Отмена</Button><Button>Сохранить</Button></div></form></Modal>}</> }

function Telegram({ integrations, chats, organizations, stores, reload }: { integrations: TelegramIntegration[]; chats: TelegramChat[]; organizations: Organization[]; stores: Store[]; reload: () => void }) {
  const [editing, setEditing] = useState<number | null>(null), [saving, setSaving] = useState(false), [error, setError] = useState('')
  const saveLinks = async (event: FormEvent<HTMLFormElement>, chatId: number) => {
    event.preventDefault(); setSaving(true); setError('')
    const form = new FormData(event.currentTarget)
    try {
      await api('/telegram/chats/' + chatId + '/links', { method: 'PUT', body: JSON.stringify({ organizationIds: form.getAll('organizationIds').map(Number), storeIds: form.getAll('storeIds').map(Number) }) })
      setEditing(null); await reload()
    } catch (reason) { setError(errorText(reason)) } finally { setSaving(false) }
  }
  return <><div className="stats-grid">{integrations.map(item => <div className="stat-card violet" key={item.id}><span><MessageCircle /></span><div><small>{item.kind === 'BOT' ? 'Telegram-бот' : 'Корпоративный аккаунт'}</small><strong style={{ fontSize: 15 }}>{item.status === 'ACTIVE' ? 'Подключён' : 'Нужна настройка'}</strong></div></div>)}</div><section className="panel table-panel"><div className="panel-head"><div><h2>Telegram-аккаунты и привязки</h2><p>Один аккаунт можно связать с несколькими организациями и точками. Для привязки пользователь должен сначала написать боту.</p></div></div>{error && <div className="form-error">{error}</div>}{chats.length ? chats.map(chat => { const organizationIds = chat.organizationLinks.map(link => link.organization.id), storeIds = chat.storeLinks.map(link => link.store.id); return <article className="telegram-row" key={chat.id}><div><b>{chat.title}</b><span>{chat.username ? '@' + chat.username : 'Без username'}</span><small>{chat.messages[0]?.body ?? 'Нет сообщений'} · {formatDate(chat.lastMessageAt)}</small><p className="telegram-links-summary">Организации: {chat.organizationLinks.length ? chat.organizationLinks.map(link => link.organization.legalName).join(', ') : 'не привязаны'}<br />Точки: {chat.storeLinks.length ? chat.storeLinks.map(link => link.store.name).join(', ') : 'не привязаны'}</p></div><Button kind="secondary" onClick={() => { setEditing(editing === chat.id ? null : chat.id); setError('') }}>{editing === chat.id ? 'Скрыть' : 'Настроить привязки'}</Button>{editing === chat.id && <form className="telegram-links-form" onSubmit={event => void saveLinks(event, chat.id)}><Field label="Организации"><select name="organizationIds" multiple defaultValue={organizationIds.map(String)}>{organizations.filter(item => item.status === 'ACTIVE').map(item => <option value={item.id} key={item.id}>{item.legalName}</option>)}</select><small>Ctrl / Cmd + клик — выбрать несколько.</small></Field><Field label="Торговые точки"><select name="storeIds" multiple defaultValue={storeIds.map(String)}>{stores.filter(item => item.status === 'ACTIVE').map(item => <option value={item.id} key={item.id}>{item.organization?.legalName ? item.organization.legalName + ' · ' : ''}{item.name} — {item.address}</option>)}</select><small>Привязка точки имеет приоритет при создании заявки ботом.</small></Field><div className="modal-actions"><Button type="submit" disabled={saving}>{saving ? 'Сохранение…' : 'Сохранить привязки'}</Button></div></form>}</article> }) : <Empty title="Telegram ещё не подключён" text="Попросите пользователя написать боту: после первого сообщения аккаунт появится в этом списке." />}</section></>
}

function Reports() {
  const firstDay = () => new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString().slice(0, 10)
  const [from, setFrom] = useState(firstDay), [to, setTo] = useState(() => new Date().toISOString().slice(0, 10)), [stats, setStats] = useState<import('./types').Stats | null>(null), [error, setError] = useState(''), [view, setView] = useState<'overview' | 'clients' | 'team' | 'requests'>('overview')
  const load = useCallback(async () => { try { setError(''); setStats(await api<import('./types').Stats>(`/requests/stats?from=${from}&to=${to}`)) } catch (reason) { setError(errorText(reason)) } }, [from, to])
  useEffect(() => { void load() }, [load])
  const list = (title: string, rows: Array<{ id: number; name: string; count: number }>) => <section className="panel table-panel"><div className="panel-head"><h2>{title}</h2></div>{rows.length ? <div className="report-list">{rows.map(row => <div key={row.id}><span>{row.name}</span><b>{row.count}</b></div>)}</div> : <p>За выбранный период данных нет.</p>}</section>
  const sourceLabel: Record<string, string> = { WEB: 'CRM / сайт', TELEGRAM_BOT: 'Telegram-бот', TELEGRAM_ACCOUNT: 'Telegram-аккаунт' }
  return <>{error && <div className="page-error">{error}</div>}<section className="panel table-panel"><div className="toolbar"><Field label="С"><input type="date" value={from} max={to} onChange={event => setFrom(event.target.value)} /></Field><Field label="По"><input type="date" value={to} min={from} onChange={event => setTo(event.target.value)} /></Field><Button kind="secondary" onClick={() => void load()}><RefreshCw /> Обновить</Button></div><div className="segmented report-tabs"><button type="button" className={view === 'overview' ? 'active' : ''} onClick={() => setView('overview')}>Сводка</button><button type="button" className={view === 'clients' ? 'active' : ''} onClick={() => setView('clients')}>Клиенты и точки</button><button type="button" className={view === 'team' ? 'active' : ''} onClick={() => setView('team')}>Команда</button><button type="button" className={view === 'requests' ? 'active' : ''} onClick={() => setView('requests')}>Реестр заявок</button></div></section>{stats && <><div className="stats-grid"><div className="stat-card coral"><span><ClipboardList /></span><div><small>Заявок за период</small><strong>{stats.total}</strong></div></div><div className="stat-card amber"><span><AlertTriangle /></span><div><small>Просрочено</small><strong>{stats.overdue}</strong></div></div><div className="stat-card green"><span><Check /></span><div><small>Выполнено</small><strong>{stats.completed}</strong></div></div><div className="stat-card violet"><span><Activity /></span><div><small>Среднее выполнение</small><strong>{stats.averageResolutionHours} ч</strong></div></div></div>{view === 'overview' && <div className="report-grid">{list('По статусам', stats.byStatus.map(item => ({ id: Object.keys(statusLabel).indexOf(item.status), name: statusLabel[item.status], count: item._count._all })))}{list('По шаблонам', stats.byType.map(item => ({ id: item.typeId, name: item.type?.name ?? 'Удалённый шаблон', count: item._count._all })))}{list('По отделам', stats.departments)}<section className="panel table-panel"><div className="panel-head"><h2>Источники обращений</h2></div><div className="report-list">{stats.sources.map(item => <div key={item.source}><span>{sourceLabel[item.source]}</span><b>{item.count}</b></div>)}</div></section></div>}{view === 'clients' && <div className="report-grid">{list('Заявки по организациям', stats.clients)}{list('Заявки по торговым точкам', stats.stores)}</div>}{view === 'team' && <div className="report-grid">{list('Нагрузка по сотрудникам', stats.employees)}{list('Заявки по отделам', stats.departments)}</div>}{view === 'requests' && <section className="panel table-panel"><div className="panel-head"><h2>Реестр заявок</h2></div><div className="report-list">{stats.requests.map(row => <div key={row.id}><span>#{row.id} · {row.organization?.legalName ?? 'Без организации'} · {row.store?.name ?? 'Без точки'}<small> {row.department.name} · {row.assignees.join(', ') || 'не назначена'} · {formatDate(row.createdAt)}</small></span><b>{statusLabel[row.status]}</b></div>)}</div></section>}</>}</>
}

function App() {
  const [user, setUser] = useState<User | null>(null), [booting, setBooting] = useState(true), [page, setPage] = useState('dashboard'), [mobileNav, setMobileNav] = useState(false), [selected, setSelected] = useState<ServiceRequest | null>(null), [createRequest, setCreateRequest] = useState(false), [calendarDate, setCalendarDate] = useState<Date | null>(null), [storeOrganizationId, setStoreOrganizationId] = useState<number | null>(null), [loadError, setLoadError] = useState('')
  const [requests, setRequests] = useState<ServiceRequest[]>([]), [stores, setStores] = useState<Store[]>([]), [organizations, setOrganizations] = useState<Organization[]>([]), [types, setTypes] = useState<RequestType[]>([]), [departments, setDepartments] = useState<Department[]>([]), [staff, setStaff] = useState<StaffMember[]>([]), [integrations, setIntegrations] = useState<TelegramIntegration[]>([]), [chats, setChats] = useState<TelegramChat[]>([])
  const load = useCallback(async () => { if (!user?.status || user.status !== 'ACTIVE') return; setLoadError(''); try { const basics = await Promise.all([api<ServiceRequest[]>('/requests'), api<Store[]>('/stores'), api<Organization[]>('/organizations'), api<RequestType[]>('/request-types'), api<Department[]>('/departments')]); setRequests(basics[0]); setStores(basics[1]); setOrganizations(basics[2]); setTypes(basics[3]); setDepartments(basics[4]); if (can(user, 'MANAGE_STAFF')) setStaff(await api<StaffMember[]>('/staff')); if (can(user, 'VIEW_TELEGRAM')) { const telegram = await Promise.all([api<TelegramIntegration[]>('/telegram/integrations'), api<TelegramChat[]>('/telegram/chats')]); setIntegrations(telegram[0]); setChats(telegram[1]) } } catch (reason) { setLoadError(errorText(reason)) } }, [user])
  useEffect(() => { restoreSession().then(setUser).finally(() => setBooting(false)) }, [])
  useEffect(() => { void load() }, [load])
  useEffect(() => { if (!user || user.status !== 'ACTIVE') return; const refresh = () => { if (document.visibilityState === 'visible') void load() }; const timer = window.setInterval(refresh, 5000); window.addEventListener('focus', refresh); document.addEventListener('visibilitychange', refresh); return () => { window.clearInterval(timer); window.removeEventListener('focus', refresh); document.removeEventListener('visibilitychange', refresh) } }, [user, load])
  const exit = async () => { await logout(); setUser(null) }
  if (booting) return <main className="boot"><RefreshCw className="spin" /> Загрузка БАЗИС CRM…</main>
  if (!user) return <Auth onAuth={setUser} />
  if (user.status !== 'ACTIVE') return <main className="state-page"><ShieldCheck /><h1>{user.status === 'REJECTED' ? 'Регистрация отклонена' : 'Регистрация на проверке'}</h1><p>{user.rejectionReason || 'Руководитель проверит учётную запись, организацию и точки.'}</p><Button kind="secondary" onClick={exit}><LogOut /> Выйти</Button></main>
  const nav = [{ id: 'dashboard', label: 'Обзор', Icon: LayoutDashboard }, { id: 'requests', label: 'Заявки', Icon: ClipboardList }, { id: 'calendar', label: 'Календарь', Icon: CalendarDays }, { id: 'organizations', label: 'Организации', Icon: Building2 }, { id: 'stores', label: 'Торговые точки', Icon: StoreIcon }, ...(can(user, 'VIEW_REPORTS') ? [{ id: 'reports', label: 'Отчёты', Icon: FileText }] : []), ...(can(user, 'MANAGE_TEMPLATES') ? [{ id: 'templates', label: 'Шаблоны', Icon: Settings2 }] : []), ...(can(user, 'MANAGE_STAFF') ? [{ id: 'staff', label: 'Сотрудники', Icon: Users }] : []), ...(can(user, 'VIEW_TELEGRAM') ? [{ id: 'telegram', label: 'Telegram', Icon: MessageCircle }] : [])]
  const urgent = requests.filter(r => r.priority === 'CRITICAL' && !['DONE', 'CANCELLED'].includes(r.status))
  const pendingOrganizations = organizations.filter(item => item.status === 'PENDING').length, pendingStores = stores.filter(item => item.status === 'PENDING').length
  const body = page === 'requests' ? <RequestsList requests={requests} user={user} departments={departments} types={types} open={item => setSelected(item)} /> : page === 'calendar' ? <Calendar requests={requests} open={item => setSelected(item)} add={date => { setCalendarDate(date); setCreateRequest(true) }} /> : page === 'organizations' ? <Organizations organizations={organizations} user={user} reload={load} openStores={organizationId => { setStoreOrganizationId(organizationId); setPage('stores') }} /> : page === 'stores' ? <Stores stores={stores} organizations={organizations} user={user} reload={load} organizationFilter={storeOrganizationId} clearFilter={() => setStoreOrganizationId(null)} /> : page === 'reports' ? <Reports /> : page === 'templates' ? <Templates types={types} departments={departments} reload={load} /> : page === 'staff' ? <Staff staff={staff} departments={departments} reload={load} /> : page === 'telegram' ? <Telegram integrations={integrations} chats={chats} organizations={organizations} stores={stores} reload={load} /> : <><div className="stats-grid"><div className="stat-card coral"><span><ClipboardList /></span><div><small>Все заявки</small><strong>{requests.length}</strong></div></div><div className="stat-card amber"><span><AlertTriangle /></span><div><small>Критические</small><strong>{urgent.length}</strong></div></div><div className="stat-card green"><span><StoreIcon /></span><div><small>Активные точки</small><strong>{stores.filter(s => s.status === 'ACTIVE').length}</strong></div></div><div className="stat-card violet"><span><Activity /></span><div><small>В работе</small><strong>{requests.filter(r => r.status === 'IN_PROGRESS').length}</strong></div></div></div><section className="panel table-panel"><div className="panel-head"><div><h2>Приоритетные заявки</h2><p>Критические и новые обращения</p></div></div><div className="request-grid">{requests.filter(r => !['DONE', 'CANCELLED'].includes(r.status)).slice(0, 6).map(item => <RequestCard key={item.id} item={item} open={() => setSelected(item)} />)}{!requests.length && <Empty title="Рабочая очередь пуста" text="Новые обращения появятся здесь." />}</div></section></>
  return <main className="app-shell"><aside className={`sidebar ${mobileNav ? 'open' : ''}`}><Brand /><div className="workspace"><span>{user.ipName.slice(0, 1)}</span><div><small>РАБОЧЕЕ ПРОСТРАНСТВО</small><b>{user.role === 'CLIENT' ? user.ipName : 'ЦТО БАЗИС'}</b></div></div><nav>{nav.map(({ id, label, Icon }) => <button className={page === id ? 'active' : ''} onClick={() => { if (id === 'stores') setStoreOrganizationId(null); setPage(id); setMobileNav(false) }} key={id}><Icon /><span>{label}</span>{((id === 'requests' && urgent.length > 0) || (id === 'organizations' && pendingOrganizations > 0) || (id === 'stores' && pendingStores > 0)) && <em>{id === 'requests' ? urgent.length : id === 'organizations' ? pendingOrganizations : pendingStores}</em>}</button>)}</nav><div className="sidebar-footer"><span className="avatar">{user.ipName.slice(0, 2).toUpperCase()}</span><div><b>{user.ipName}</b><small>{roleLabel[user.role]}</small></div><button onClick={exit}><LogOut /></button></div></aside>{mobileNav && <button className="nav-scrim" onClick={() => setMobileNav(false)} />}<section className="content"><header><button className="menu-button" onClick={() => setMobileNav(true)}><Menu /></button><div className="breadcrumb">БАЗИС CRM / {nav.find(n => n.id === page)?.label}</div><div className="header-actions"><Button kind="secondary" onClick={() => void load()}><RefreshCw /> Обновить</Button></div></header><div className="page"><div className="title-row"><div><span className="eyebrow">{roleLabel[user.role]}</span><h1>{nav.find(n => n.id === page)?.label}</h1><p>{page === 'dashboard' ? 'Рабочая картина по доступным вам заявкам.' : 'Данные отображаются с учётом индивидуальных прав.'}</p></div>{page === 'requests' && <Button onClick={() => { setCalendarDate(null); setCreateRequest(true) }}><Plus /> Новая заявка</Button>}</div>{loadError && <div className="page-error">{loadError}</div>}{body}</div></section>{selected && <RequestModal item={selected} user={user} departments={departments} close={() => setSelected(null)} reload={load} />}{createRequest && <CreateRequest organizations={organizations} stores={stores} types={types} close={() => { setCreateRequest(false); setCalendarDate(null) }} reload={load} initialUrgency={calendarDate ? 'SCHEDULED' : 'URGENT'} initialScheduledAt={calendarDate} />}</main>
}

export default App
